import assert from 'node:assert';
import { createState, frame, ballSpeed } from '../game/neon.js';

// Mock canvas context
const ctx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('D1: Basic Vertical Bounce (Bottom Face)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Ball moving UP, hitting the bottom face
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h - 1; // overlap
  state.ball.vy = -100; 

  frame(ctx, state);

  assert.ok(state.ball.vy > 0, `Ball should bounce DOWN (vy > 0), but got ${state.ball.vy}`);
});

test('D1: Basic Horizontal Bounce (Left Face)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Ball moving RIGHT, hitting the left face
  state.ball.x = brick.x - 1; // overlap
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100;

  frame(ctx, state);

  assert.ok(state.ball.vx < 0, `Ball should bounce LEFT (vx < 0), but got ${state.ball.vx}`);
});

test('D2: Tunneling at Level 6', () => {
  const state = createState(6);
  const brick = state.bricks[0];

  // Ball is just below the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 1; 
  state.ball.vy = -ballSpeed(6); // -710 px/s

  // Simulate one frame with max dt (0.05s)
  // In the current game loop, step() is called before frame()
  // But the collision logic is in frame()

  // We simulate the position the ball would be at after step()
  const dt = 0.05;
  const nextY = state.ball.y + state.ball.vy * dt; // 7.2 + (-710 * 0.05) = 7.2 - 35.5 = -28.3

  // The ball was at y=31, now it's at y=-28. The brick is at y=48, h=20 (bottom=68).
  // Wait, the ball is moving UP.
  // Initial y = brick.y + brick.h + 1 = 48 + 20 + 1 = 69.
  // After step: y = 69 + (-710 * 0.05) = 69 - 35.5 = 33.5.
  // The brick top is at 48. So the ball is now ABOVE the brick.
  // In between, it passed through.

  state.ball.y = nextY;
  frame(ctx, state);

  // Since it's discrete, if it never overlapped at the start or end of frame, 
  // no collision is detected.
  assert.ok(brick.alive === false, 'Ball should have hit the brick even when tunneling');
});
